const j = $input.item.json;
const has = (v) => v !== undefined && v !== null && String(v).trim() !== '' && String(v) !== 'undefined' && String(v) !== 'null';
const clip = (v, n) => { const s = String(v).trim(); return s.length > n ? s.slice(0, n) + '...' : s; };
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const headers = {
  new_project: 'NEW PROJECT REQUEST',
  manual_review: 'MANUAL REVIEW NEEDED',
  agent_stuck: 'AI AGENT NEEDS HELP',
  payment: 'PAYMENT CONFIRMED',
  payment_proof: 'PAYMENT PROOF - VERIFY MANUALLY',
  critical_error: 'CRITICAL WORKFLOW ERROR',
  info: 'SESEMI UPDATE',
};
let eventType = has(j.event_type) ? String(j.event_type).trim().toLowerCase() : 'info';
if (!headers[eventType]) eventType = 'info';
const lines = [];
lines.push('<b>' + headers[eventType] + '</b>');
if (has(j.title)) lines.push('<b>' + esc(clip(j.title, 200)) + '</b>');
lines.push('');
const field = (label, v, n) => { if (has(v)) lines.push('<b>' + label + ':</b> ' + esc(clip(v, n || 300))); };
field('Project', j.project_code);
field('Customer', j.customer_name);
field('Email', j.customer_email);
field('Requirements', j.requirements_summary, 900);
field('Proposed solution', j.proposed_solution, 900);
field('Plan', j.plan_tier);
const prices = [];
if (has(j.setup_price_usd)) prices.push('$' + j.setup_price_usd + ' setup');
if (has(j.monthly_price_usd)) prices.push('$' + j.monthly_price_usd + '/month');
if (prices.length) lines.push('<b>Estimated price:</b> ' + esc(prices.join(' + ')));
if (has(j.timeline_days)) lines.push('<b>Timeline:</b> ' + esc(j.timeline_days) + ' days');
field('Complexity', j.complexity);
if (eventType === 'payment_proof' || eventType === 'payment') {
  lines.push('');
  if (has(j.payment_amount_usdt)) lines.push('<b>Expected amount:</b> ' + esc(j.payment_amount_usdt) + ' USDT');
  field('Network', j.network_label);
  if (has(j.receiving_address)) lines.push('<b>Receiving address:</b> <code>' + esc(j.receiving_address) + '</code>');
  if (has(j.tx_hash)) {
    lines.push('<b>TX hash:</b> <code>' + esc(clip(j.tx_hash, 120)) + '</code>');
    lines.push('<a href="https://tronscan.org/#/transaction/' + encodeURIComponent(String(j.tx_hash).trim()) + '">Verify on TronScan</a>');
  }
}
if (has(j.details)) { lines.push(''); lines.push('<b>Details:</b>'); lines.push(esc(clip(j.details, 1500))); }
let text = lines.join('\n');
if (text.length > 4000) text = text.slice(0, 3990) + '...';
let showButtons = has(j.show_buttons) ? String(j.show_buttons).trim().toLowerCase() : 'none';
if (showButtons !== 'approve_reject' && showButtons !== 'verify_payment') showButtons = 'none';
const code = has(j.project_code) ? String(j.project_code).trim() : '';
if (!code) showButtons = 'none';
let b1 = '', d1 = '', b2 = '', d2 = '';
if (showButtons === 'approve_reject') { b1 = 'APPROVE'; d1 = 'approve:' + code; b2 = 'REJECT'; d2 = 'reject:' + code; }
if (showButtons === 'verify_payment') { b1 = 'PAYMENT VERIFIED'; d1 = 'paid:' + code; b2 = 'PAYMENT NOT FOUND'; d2 = 'unpaid:' + code; }
return { json: { event_type: eventType, project_code: code, message_text: text, show_buttons: showButtons, btn1_text: b1, btn1_data: d1, btn2_text: b2, btn2_data: d2 } };

const j = $input.item.json;
const stripTags = (s) => String(s).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const asText = (v) => {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join(', ');
  if (typeof v === 'object') {
    if (Array.isArray(v.value) && v.value[0]) {
      const a = v.value[0];
      return (a.name ? a.name + ' <' + a.address + '>' : (a.address || a.email || ''));
    }
    if (v.text) return String(v.text);
    if (v.html) return stripTags(v.html);
    if (v.value) return asText(v.value);
  }
  return String(v);
};
const decode = (d) => Buffer.from(String(d).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
const h = j.headers || {};
const subject = asText(j.subject) || asText(h.subject) || asText(h.Subject) || '(no subject)';
const from = asText(j.from) || asText(h.from) || asText(h.From) || '(unknown sender)';
const date = asText(j.date) || asText(h.date) || asText(h.Date) || '';
let body = '';
const walk = (p) => {
  if (!p) return '';
  const mime = String(p.mimeType || '');
  if ((mime.startsWith('text/plain') || mime.startsWith('text/html')) && p.body && p.body.data) {
    return mime.startsWith('text/html') ? stripTags(decode(p.body.data)) : String(decode(p.body.data)).replace(/\s+/g, ' ');
  }
  for (const c of (p.parts || [])) { const t = walk(c); if (t) return t; }
  return '';
};
if (j.payload) { body = walk(j.payload); }
if (!body && j.textPlain) body = stripTags(j.textPlain);
if (!body && j.textHtml) body = stripTags(j.textHtml);
if (!body && j.text) body = stripTags(j.text);
if (!body && j.snippet) body = stripTags(j.snippet);
const clip = (s, n) => { s = String(s); return s.length > n ? s.slice(0, n) + '...' : s; };
return { json: {
  email_id: j.id || '',
  thread_id: j.threadId || '',
  from: clip(from, 150),
  subject: clip(subject, 200),
  date: String(date),
  body: clip(body || '(empty message body)', 6000)
} };

const text = String($('Telegram Trigger').item.json.message.text || '').trim();
const lower = text.toLowerCase();
const base = { mission_code: '', goal: '', source: 'telegram', task_seq: null, task_status: '', result_note: '' };
if (lower.startsWith('/tasks')) {
  const parts = text.split(/\s+/);
  if (parts.length > 1) return { json: Object.assign({}, base, { action: 'get_mission', mission_code: parts[1].toUpperCase() }) };
  return { json: Object.assign({}, base, { action: 'list_tasks' }) };
}
if (lower.startsWith('/mission')) {
  return { json: Object.assign({}, base, { action: 'create_mission', goal: text.slice(8).trim() }) };
}
return { json: Object.assign({}, base, { action: 'unknown' }) };
